/**
 * Build a `voice.Agent` from a `LuaVoice` for in-process testing.
 *
 * Distinct from the production `compiled-voice-agent` in lua-livekit:
 *   - No artifact loader, no bundle decompression — the dev's hooks are
 *     plain JS functions on the imported LuaVoice; we wire them directly.
 *   - No platform-API sandbox — tests run in the dev's own jest process,
 *     mock platform APIs via globals or by passing stubs.
 *   - No real STT/TTS/VAD — `voice.AgentSession` test mode skips audio
 *     entirely; only the LLM (Fake or dev-supplied) actually drives turns.
 */

import { llm, voice } from '@livekit/agents';
import type { LuaVoice, LuaVoiceHookContext, LuaVoiceTurnContext } from '../../types/voice.js';
import type { LuaTool } from '../../types/skill.js';

export interface BuildTestAgentOptions {
  voice: LuaVoice;
  /** Mocked LLM that scripts the agent's responses. */
  llm: llm.LLM;
  /** Caller info passed to onEnter / onExit hook ctx. */
  caller?: { phoneNumber?: string; userId?: string; isAnonymous?: boolean };
  channel?: 'phone' | 'meeting' | 'whatsapp' | 'webchat';
  sessionId?: string;
  /** Pre-seeded sessionview userdata (what onEnter would normally hydrate). */
  initialUserdata?: Record<string, unknown>;
  /**
   * Map of tool name → mock execute. When set, the harness substitutes
   * the dev's `tool.execute` with the mock. Tools without a mock keep
   * their real execute (which may itself stub external calls).
   */
  mockTools?: Record<string, (input: unknown, ctx?: unknown) => unknown>;
  /**
   * Other LuaVoices reachable via `ctx.voice.handoff(name)`. The harness
   * builds a stub Agent for the target on demand so RunResult emits an
   * agent_handoff event the matcher can assert on.
   */
  handoffTargets?: Record<string, LuaVoice>;
  /** Lazy session reference, populated by run-voice after start(). */
  sessionRef?: { current: voice.AgentSession | null };
  /**
   * Spy on `ctx.voice.transferToHuman(...)` calls. Real REFER / bridge
   * doesn't fire in the harness; this callback is the assertion hook
   * for tests that exercise the dev's transfer logic. No-op when
   * absent.
   */
  onTransferToHuman?: TransferToHumanRecorder;
}

export function buildTestAgent(opts: BuildTestAgentOptions): voice.Agent {
  const { voice: lv } = opts;
  const sessionId = opts.sessionId ?? `test-${Date.now()}`;
  const channel = opts.channel ?? 'phone';
  const userdata: Record<string, unknown> = { ...(opts.initialUserdata ?? {}) };
  const enteredAt = Date.now();
  const sessionRef = opts.sessionRef ?? { current: null };

  // Build the LiveKit ToolContext from the LuaVoice's tools.
  const tools = buildToolContext(lv.tools, opts.mockTools, {
    sessionRef,
    handoffTargets: opts.handoffTargets,
    llm: opts.llm,
    onTransferToHuman: opts.onTransferToHuman,
  });

  // Persona becomes Agent.instructions. LuaVoice doesn't carry persona
  // directly; the production worker reads it from the bound LuaAgent's
  // persona via artifact-loader. For tests, default to greeting + a
  // minimal stub — devs can override with mockLLM if they need richer
  // persona-driven behavior in the LLM responses themselves.
  const instructions = lv.greeting ?? '';

  class TestVoiceAgent extends voice.Agent {
    constructor() {
      super({
        instructions,
        tools,
        llm: opts.llm,
        // No STT / TTS / VAD — test mode skips audio.
      });
    }
    // Override the SDK's `id` getter so handoff matchers can identify
    // which LuaVoice this agent represents. LiveKit's RunResult
    // agent_handoff event exposes the new agent instance — devs assert
    // via name.
    override get id(): string {
      return lv.name;
    }

    override async onEnter(): Promise<void> {
      if (!lv.onEnter) return;
      const ctx = buildHookContext({
        session: this.session,
        sessionId,
        channel,
        caller: opts.caller,
        userdata,
        enteredAt,
      });
      await lv.onEnter(ctx);
    }

    override async onUserTurnCompleted(chatCtx: llm.ChatContext, newMessage: llm.ChatMessage): Promise<void> {
      if (!lv.onUserTurnCompleted) return;
      const turnCtx: LuaVoiceTurnContext = {
        items: chatCtx.items,
        addMessage: ({ role, content }) => {
          // Mirror lua-livekit's compiled-voice-agent: forward to the
          // chatCtx so the LLM sees the injected RAG context on the next
          // turn. Tests assert via `result.expect.containsMessage`.
          (chatCtx as unknown as { addMessage: (m: { role: string; content: string }) => void }).addMessage({
            role,
            content,
          });
        },
      };
      const userText = extractTextContent(newMessage.content);
      await lv.onUserTurnCompleted(turnCtx, { content: userText });
    }

    override async onExit(): Promise<void> {
      if (!lv.onExit) return;
      const ctx = buildHookContext({
        session: this.session,
        sessionId,
        channel,
        caller: opts.caller,
        userdata,
        enteredAt,
      });
      await lv.onExit(ctx);
    }
  }

  return new TestVoiceAgent();
}

/**
 * Wrap each LuaTool / LuaVoiceTool in a LiveKit `llm.tool({})` so the
 * AgentSession can dispatch tool calls. The mockTools map overrides the
 * dev's `execute` when provided.
 */
/**
 * Optional spy on `ctx.voice.transferToHuman(msisdn, opts)` calls
 * inside the test harness. Real SIP REFER / bridge dial doesn't fire
 * in tests — the harness has no SipClient — so this is the only way
 * to assert "the dev's tool tried to transfer to a human". Default is
 * a no-op log.
 */
export type TransferToHumanRecorder = (
  msisdn: string,
  opts?: { mode?: 'bridge' | 'refer'; announce?: string }
) => Promise<void> | void;

interface BuildToolContextOptions {
  sessionRef: { current: voice.AgentSession | null };
  handoffTargets?: Record<string, LuaVoice>;
  llm: llm.LLM;
  /** Test-time hook for `ctx.voice.transferToHuman`. */
  onTransferToHuman?: TransferToHumanRecorder;
}

function buildToolContext(
  tools: ReadonlyArray<
    | LuaTool<any>
    | {
        name: string;
        description?: string;
        inputSchema?: unknown;
        execute?: (input: any, ctx?: any) => any;
        voice?: { flags?: string[] };
      }
  >,
  mockTools: Record<string, (input: unknown, ctx?: unknown) => unknown> | undefined,
  opts: BuildToolContextOptions
): llm.ToolContext {
  const ctx: llm.ToolContext = {};
  for (const t of tools) {
    if (!t || !t.name || !t.execute) continue;
    const mock = mockTools?.[t.name];
    const execute = mock ?? t.execute;
    ctx[t.name] = llm.tool({
      description: t.description ?? '',
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      parameters: (t.inputSchema as any) ?? undefined,
      execute: async (input: unknown, toolCtx: { toolCallId: string }) => {
        return execute(input, buildToolCallCtx(toolCtx, opts));
      },
    });
  }
  return ctx;
}

function buildToolCallCtx(
  livekitCtx: { toolCallId: string },
  opts: BuildToolContextOptions
): {
  toolCallId: string;
  voice: {
    say: (text: string) => Promise<void>;
    transferToHuman: (msisdn: string, opts?: { mode?: 'bridge' | 'refer'; announce?: string }) => Promise<void>;
    handoff: (name: string) => void;
  };
} {
  return {
    toolCallId: livekitCtx.toolCallId,
    voice: {
      say: async (text: string) => {
        opts.sessionRef.current?.say(text);
      },
      transferToHuman: async (msisdn: string, transferOpts?: { mode?: 'bridge' | 'refer'; announce?: string }) => {
        // The harness can't actually transfer a SIP leg — no real
        // SipClient, no real room. Delegate to the dev's recorder if
        // they passed one (lets tests assert "the agent attempted a
        // transfer to +32..."); otherwise no-op so the dev's tool
        // doesn't crash mid-test.
        if (transferOpts?.announce) opts.sessionRef.current?.say(transferOpts.announce);
        if (opts.onTransferToHuman) await opts.onTransferToHuman(msisdn, transferOpts);
      },
      handoff: (name: string) => {
        const target = opts.handoffTargets?.[name];
        if (!target) {
          throw new Error(
            `Voice "${name}" not registered as handoff target. Pass it via runVoice({ handoffTargets: { ${name}: ${name}Voice } }).`
          );
        }
        const session = opts.sessionRef.current;
        if (!session) {
          throw new Error('handoff() called before session start.');
        }
        const targetAgent = buildTestAgent({
          voice: target,
          llm: opts.llm,
          sessionRef: opts.sessionRef,
          handoffTargets: opts.handoffTargets,
          onTransferToHuman: opts.onTransferToHuman,
        });
        session.updateAgent(targetAgent);
      },
    },
  };
}

interface BuildHookContextArgs {
  session: voice.AgentSession;
  sessionId: string;
  channel: string;
  caller?: { phoneNumber?: string; userId?: string; isAnonymous?: boolean };
  userdata: Record<string, unknown>;
  enteredAt: number;
}

function buildHookContext(args: BuildHookContextArgs): LuaVoiceHookContext {
  return {
    sessionId: args.sessionId,
    channel: { kind: args.channel },
    caller: args.caller,
    duration: Math.floor((Date.now() - args.enteredAt) / 1000),
    session: {
      userdata: args.userdata,
      history: args.session.chatCtx?.items ?? [],
      say: async (text: string) => {
        args.session.say(text);
      },
      generateReply: (replyOpts?: { instructions?: string }) => {
        return args.session.generateReply(replyOpts ?? {});
      },
    },
  };
}

function extractTextContent(content: llm.ChatMessage['content']): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map((part) => (typeof part === 'string' ? part : ((part as { text?: string }).text ?? ''))).join('');
}
