/**
 * `lua-cli/voice/test` — public surface for `lua voice test` files.
 *
 * Devs import from `lua-cli/voice/test`:
 *
 * ```typescript
 * import { runVoice, expectContainsMessage, expectCalledTool, expectContainsHandoff, judge } from 'lua-cli/voice/test';
 * import support from './support.voice';
 *
 * it('looks up the order', async () => {
 *   const session = await runVoice(support, {
 *     llm: [
 *       { input: 'Where is order ABC?', toolCalls: [{ name: 'lookup_order', args: { id: 'ABC' } }] },
 *       { input: '', content: 'Order ABC was shipped Tuesday.' },
 *     ],
 *     mockTools: { lookup_order: ({ id }) => ({ id, status: 'shipped' }) },
 *   });
 *   const result = await session.run('Where is order ABC?');
 *   expectCalledTool(result, 'lookup_order', { id: 'ABC' });
 *   expectContainsMessage(result, /shipped/);
 * });
 * ```
 *
 * Re-exports are kept thin — LiveKit's `RunResult` and `FakeLLM` are
 * surfaced for devs who want native control beyond the helpers.
 */

export { runVoice, type TestSession, type RunVoiceOptions } from './run-voice.js';
export { expectContainsMessage, expectCalledTool, expectContainsHandoff } from './matchers.js';
export { judge, expectJudge, type JudgeOptions } from './judge.js';

// Re-export LiveKit primitives so devs only depend on lua-cli.
// `voice.testing` is a namespace inside the agents root export, not a
// subpath; access via `voice.testing.X`.
export { llm, voice } from '@livekit/agents';
