/**
 * `runVoice` — bootstrap a LuaVoice into a LiveKit `voice.AgentSession`
 * test harness. Returns a TestSession the dev drives turn-by-turn.
 *
 * The harness is text-driven (no audio, no real STT/TTS/VAD) and runs
 * inside the dev's jest process. Production code paths (sandbox, bundle
 * decompression, lua-agents fetch) are bypassed — the dev's hooks are
 * imported directly from their source.
 *
 * Multi-turn semantics: the same AgentSession is reused across `run()`
 * calls so chat_ctx persists. Devs assert per-turn via `RunResult.expect`
 * or globally via `session.history` / `session.events`.
 */

import { llm, voice } from '@livekit/agents';
import type { LuaVoice } from '../../types/voice.js';
import { buildTestAgent } from './test-agent.js';

type FakeLLMResponse = voice.testing.FakeLLMResponse;
type RunResult = voice.testing.RunResult;
const FakeLLM = voice.testing.FakeLLM;

export interface RunVoiceOptions {
  /**
   * LLM mock script. Each entry is keyed by the user input text — when
   * the agent's chat loop hits that input, the FakeLLM returns the
   * paired content/toolCalls. Devs can pass a pre-built `llm.LLM`
   * instance instead for full control (custom matching, multi-turn
   * stateful responses, etc.).
   */
  llm?: FakeLLMResponse[] | llm.LLM;
  /**
   * Mock tool executions. Substitutes the dev's tool.execute for the
   * named tool — return value flows into the LLM's next turn the same
   * way a real execute would.
   */
  mockTools?: Record<string, (input: unknown, ctx?: unknown) => unknown>;
  /** Caller info passed to onEnter / onExit hook ctx. */
  caller?: { phoneNumber?: string; userId?: string; isAnonymous?: boolean };
  channel?: 'phone' | 'meeting' | 'whatsapp' | 'webchat';
  /** Pre-seeded session.userdata. Same as the worker's initial state when onEnter hasn't run yet. */
  initialUserdata?: Record<string, unknown>;
  /**
   * Other LuaVoices the agent under test can hand off to. Pass each
   * target voice keyed by name so `ctx.voice.handoff('billing-line')`
   * resolves; assertion happens via `expectContainsHandoff(result, 'billing-line')`.
   */
  handoffTargets?: Record<string, import('../../types/voice.js').LuaVoice>;
  /**
   * Spy on `ctx.voice.transferToHuman(...)` calls from inside the
   * voice's tools. Real SIP REFER / bridge dial never fires under
   * the test harness — pass a jest.fn() (or any callback) to assert
   * the dev's tool attempted a transfer.
   */
  onTransferToHuman?: import('./test-agent.js').TransferToHumanRecorder;
  /**
   * Seed `dispatchedContext` (what `Voice.call({ context })` would
   * inject in production). Stored on session.userdata under the same
   * key the worker uses, plus made available to the hook ctx.
   */
  dispatchedContext?: Record<string, unknown>;
  sessionId?: string;
}

export interface TestSession {
  /**
   * Drive a single user turn. Returns a `RunResult` (LiveKit's
   * built-in assertion type) — chain `.expect.nextEvent()` /
   * `.expect.containsFunctionCall()` / etc. on the result.
   */
  run(userInput: string): Promise<voice.testing.RunResult>;
  /**
   * Drive multiple turns sequentially, returning all results in order.
   */
  runMany(userInputs: string[]): Promise<voice.testing.RunResult[]>;
  /** Direct access to the underlying LiveKit AgentSession. */
  readonly session: voice.AgentSession;
  /** The chat history accumulated across all turns. */
  readonly history: ReadonlyArray<unknown>;
  /** Call the LuaVoice's onExit hook (mirror end-of-session lifecycle). */
  close(): Promise<void>;
}

export async function runVoice(luaVoice: LuaVoice, options: RunVoiceOptions = {}): Promise<TestSession> {
  const fakeLlm =
    options.llm instanceof Object && 'chat' in (options.llm as object)
      ? (options.llm as llm.LLM)
      : new FakeLLM((options.llm as FakeLLMResponse[]) ?? []);

  // Seed initialUserdata with dispatchedContext so dev hooks see what
  // the production worker sees. The worker stamps it via
  // `session.userdata.dispatchedContext` after seeding chat_ctx with a
  // system message — we mirror only the userdata side here; tests that
  // care about the system-message seed should assert on chat_ctx items.
  const initialUserdata = {
    ...(options.initialUserdata ?? {}),
    ...(options.dispatchedContext ? { dispatchedContext: options.dispatchedContext } : {}),
  };

  const sessionRef: { current: voice.AgentSession | null } = { current: null };
  const agent = buildTestAgent({
    voice: luaVoice,
    llm: fakeLlm,
    caller: options.caller,
    channel: options.channel,
    sessionId: options.sessionId,
    initialUserdata,
    mockTools: options.mockTools,
    handoffTargets: options.handoffTargets,
    onTransferToHuman: options.onTransferToHuman,
    sessionRef,
  });

  // No stt/tts/vad — test mode runs the LLM-only loop. The session's
  // start() wires the agent without a room.
  const session = new voice.AgentSession({
    llm: fakeLlm,
  } as ConstructorParameters<typeof voice.AgentSession>[0]);
  sessionRef.current = session;

  // start(agent) is what activates the session for `session.run()`. No
  // room argument needed in test mode — `voice.AgentSession.run()` is
  // explicitly designed to skip room connection.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  await (session as unknown as { start: (a: voice.Agent) => Promise<void> }).start(agent);

  const testSession: TestSession = {
    session,
    get history() {
      return session.chatCtx?.items ?? [];
    },
    async run(userInput: string): Promise<voice.testing.RunResult> {
      const result = session.run({ userInput });
      await result.wait();
      return result;
    },
    async runMany(inputs: string[]): Promise<voice.testing.RunResult[]> {
      const out: voice.testing.RunResult[] = [];
      for (const input of inputs) {
        out.push(await testSession.run(input));
      }
      return out;
    },
    async close(): Promise<void> {
      if (luaVoice.onExit) {
        // `agent.onExit` already wraps this when the session shuts
        // down naturally; tests use this hook to assert post-call
        // behavior without spinning up the full close path.
        await (agent as unknown as { onExit: () => Promise<void> }).onExit();
      }
      await session.close();
    },
  };

  return testSession;
}
