/**
 * LLM-as-judge: use an LLM to evaluate an agent response against a
 * natural-language criterion. Returns true when the judge agrees the
 * criterion holds.
 *
 * Use for soft assertions where regex/substring would be brittle —
 * "the agent acknowledged the refund" could be phrased a hundred ways.
 * For hard contracts (tool was called, handoff happened) prefer the
 * exact matchers in `matchers.ts`.
 *
 * Trade-offs (see audit M-4):
 *   - Non-deterministic: same input may flip between runs.
 *   - Costs tokens per assertion: a CI suite with 100 judge calls
 *     adds up.
 *   - Stronger judge (gpt-5, claude-opus) is more consistent than a
 *     cheap one.
 *
 * The dev passes their own LLM instance to keep judge cost + provider
 * choice explicit.
 */

import { llm } from '@livekit/agents';

export interface JudgeOptions {
  /** LLM instance the judge prompt runs against. */
  llm: llm.LLM;
  /**
   * Optional system instruction override. The default keeps the judge
   * strict ("answer yes or no, no explanation"). Override when you need
   * the judge to score on a scale or return structured output — though
   * structured output is more brittle than yes/no.
   */
  systemInstruction?: string;
  /**
   * Optional context. When set, the judge sees additional facts
   * before scoring the response. Useful for "did the agent answer
   * factually given these facts": pass the facts as `context`.
   */
  context?: string;
}

const DEFAULT_SYSTEM = [
  'You are a strict evaluator. Given an agent response and a criterion,',
  'decide whether the response satisfies the criterion. Reply with ONLY',
  'the single word "yes" or "no" — no explanation, no punctuation.',
].join(' ');

/**
 * Returns true when the judge LLM concludes the response satisfies the
 * criterion. False on disagreement OR on any judge failure (network,
 * malformed response, timeout) — fail-closed so a flaky judge doesn't
 * mask a real assertion failure.
 */
export async function judge(response: string, criterion: string, options: JudgeOptions): Promise<boolean> {
  const system = options.systemInstruction ?? DEFAULT_SYSTEM;
  const userParts = [
    `Agent response: "${response.replace(/"/g, '\\"')}"`,
    options.context ? `Context: ${options.context}` : null,
    `Criterion: "${criterion.replace(/"/g, '\\"')}"`,
  ]
    .filter(Boolean)
    .join('\n');

  const chatCtx = createChatContext(system, userParts);
  const stream = options.llm.chat({ chatCtx });
  const text = await collectText(stream);
  const verdict = text.trim().toLowerCase().split(/\s+/)[0];
  return verdict === 'yes' || verdict === 'true' || verdict === 'pass';
}

/**
 * Throwing variant for jest-style tests. Throws an Error with the
 * judge's verdict + the original criterion when the judge says no, so
 * the failure message in the test report is self-explanatory.
 */
export async function expectJudge(response: string, criterion: string, options: JudgeOptions): Promise<void> {
  const ok = await judge(response, criterion, options);
  if (!ok) {
    throw new Error(`LLM judge rejected:\n  criterion: ${criterion}\n  response: ${response}`);
  }
}

// --- internals ---

function createChatContext(system: string, user: string): llm.ChatContext {
  const ctx = new llm.ChatContext();
  const add = (ctx as unknown as { addMessage: (m: { role: string; content: string }) => void }).addMessage.bind(ctx);
  add({ role: 'system', content: system });
  add({ role: 'user', content: user });
  return ctx;
}

async function collectText(stream: llm.LLMStream): Promise<string> {
  let out = '';
  for await (const chunk of stream as unknown as AsyncIterable<{ delta?: { content?: string } }>) {
    out += chunk.delta?.content ?? '';
  }
  return out;
}
