/**
 * Convenience wrappers around LiveKit's `RunAssert` API. The native
 * `result.expect.containsMessage(...)` etc. is already strong; these
 * exports give devs Jest-style helpers (`expectContainsHandoff(result,
 * 'billing-line')`) without needing to learn LiveKit's specific assert
 * chain.
 */

import type { voice } from '@livekit/agents';

type RunResult = voice.testing.RunResult;

/**
 * Assert the run produced an assistant message matching the predicate.
 * Predicate can be a substring, a regex, or a custom function.
 */
export function expectContainsMessage(result: RunResult, matcher: string | RegExp | ((text: string) => boolean)): void {
  const messages = (result.events as readonly unknown[])
    .filter(isMessageEvent)
    .filter((e) => e.item.role === 'assistant');
  const texts = messages.map((m) => contentToText(m.item.content));
  const matched = texts.some((t) => predicateMatch(t, matcher));
  if (!matched) {
    throw new Error(
      `Expected assistant message matching ${describeMatcher(matcher)}; got:\n${texts.map((t) => `  - ${t}`).join('\n') || '  (no assistant messages)'}`
    );
  }
}

/**
 * Assert the run invoked a specific tool. Optional args matcher narrows
 * to a specific call shape.
 */
export function expectCalledTool(
  result: RunResult,
  toolName: string,
  expectedArgs?: Record<string, unknown> | ((args: unknown) => boolean)
): void {
  const calls = (result.events as readonly unknown[])
    .filter(isFunctionCallEvent)
    .filter((e) => e.item.name === toolName);
  if (calls.length === 0) {
    const namesSeen =
      (result.events as readonly unknown[])
        .filter(isFunctionCallEvent)
        .map((e) => e.item.name)
        .join(', ') || '(no tool calls)';
    throw new Error(`Expected tool call to "${toolName}"; saw: ${namesSeen}`);
  }
  if (expectedArgs === undefined) return;

  const matched = calls.some((c) => {
    const parsed = parseToolArgs(c.item.arguments);
    if (typeof expectedArgs === 'function') return expectedArgs(parsed);
    return shallowSubset(expectedArgs, parsed);
  });
  if (!matched) {
    const seen = calls.map((c) => parseToolArgs(c.item.arguments));
    throw new Error(
      `Expected tool "${toolName}" called with ${JSON.stringify(expectedArgs)}; saw:\n${seen.map((s) => `  - ${JSON.stringify(s)}`).join('\n')}`
    );
  }
}

/**
 * Assert the run produced an agent handoff. By name (the LuaVoice's
 * `name` field), since the test harness doesn't have access to the
 * Agent constructor types LiveKit's `containsAgentHandoff` expects.
 */
export function expectContainsHandoff(result: RunResult, voiceName: string): void {
  const handoffs = (result.events as readonly unknown[]).filter(isHandoffEvent);
  if (handoffs.length === 0) {
    throw new Error(`Expected handoff to "${voiceName}"; no handoff events emitted.`);
  }
  const matched = handoffs.some(
    (h) => h.newAgent?.id === voiceName || (h.item as { agentName?: string }).agentName === voiceName
  );
  if (!matched) {
    const seen = handoffs.map((h) => h.newAgent?.id ?? '(unnamed)').join(', ');
    throw new Error(`Expected handoff to "${voiceName}"; got handoffs to: ${seen}`);
  }
}

// --- internals ---

function predicateMatch(text: string, matcher: string | RegExp | ((text: string) => boolean)): boolean {
  if (typeof matcher === 'string') return text.includes(matcher);
  if (matcher instanceof RegExp) return matcher.test(text);
  return matcher(text);
}

function describeMatcher(matcher: string | RegExp | ((text: string) => boolean)): string {
  if (typeof matcher === 'string') return `substring "${matcher}"`;
  if (matcher instanceof RegExp) return `regex ${matcher.toString()}`;
  return 'custom predicate';
}

function contentToText(content: unknown): string {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map((part) => (typeof part === 'string' ? part : ((part as { text?: string }).text ?? ''))).join('');
}

function parseToolArgs(args: unknown): unknown {
  if (typeof args !== 'string') return args;
  try {
    return JSON.parse(args);
  } catch {
    return args;
  }
}

function shallowSubset(expected: Record<string, unknown>, actual: unknown): boolean {
  if (!actual || typeof actual !== 'object') return false;
  const a = actual as Record<string, unknown>;
  for (const [k, v] of Object.entries(expected)) {
    if (a[k] !== v) return false;
  }
  return true;
}

interface MessageEvent {
  type: 'message';
  item: { role: string; content: unknown };
}
interface FunctionCallEvent {
  type: 'function_call';
  item: { name: string; arguments: unknown };
}
interface HandoffEvent {
  type: 'agent_handoff';
  item: { agentName?: string };
  newAgent?: { id?: string };
}

function isMessageEvent(e: unknown): e is MessageEvent {
  return !!e && (e as { type?: string }).type === 'message';
}

function isFunctionCallEvent(e: unknown): e is FunctionCallEvent {
  return !!e && (e as { type?: string }).type === 'function_call';
}

function isHandoffEvent(e: unknown): e is HandoffEvent {
  return !!e && (e as { type?: string }).type === 'agent_handoff';
}
